import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Sovereign Edge — Epics Overview","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/README.md"},"headers":[],"relativePath":"sovereign-edge/epics/README.md","filePath":"sovereign-edge/epics/README.md"}'),r={name:"sovereign-edge/epics/README.md"};function n(s,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="sovereign-edge-—-epics-overview" tabindex="-1">Sovereign Edge — Epics Overview <a class="header-anchor" href="#sovereign-edge-—-epics-overview" aria-label="Permalink to &quot;Sovereign Edge — Epics Overview&quot;">​</a></h1><p>A domain-first map of all Sovereign Edge work streams, cross-cutting the phase-sequenced <a href="./../../ROADMAP.html">roadmap</a>. Each epic collects related tasks regardless of when they&#39;re planned or shipped. Tasks within each epic carry a stable ID (<code>&lt;epic&gt;.&lt;seq&gt;</code>) that can be cited in doc cross-references and dependency lists (not commit messages or PR titles — see <a href="./../../CONTRIBUTING.html#branching-and-commits">CONTRIBUTING.md</a>).</p><p>Full concept and architecture: <a href="./../../CONCEPT.html">CONCEPT.md</a>. Decision record behind this shape: <a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a>.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>Epics live in one of three directories, matching each file&#39;s own <code>scope:</code> frontmatter — this is a structural split, not just a tag, so a file&#39;s location always tells you where its code ships:</p><ul><li><strong><code>mobile/</code></strong> — ships inside <code>apps/mobile</code> today.</li><li><strong><code>desktop/</code></strong> — ships inside <code>apps/desktop</code>, once it exists.</li><li><strong><code>shared/</code></strong> — platform-neutral by design, not owned by one app (the Connector SDK and Monetization epics: both are structured from the start to span mobile and desktop, not implemented in one first and ported later).</li></ul><p>An epic&#39;s directory reflects what its deliverables target <em>today</em>, not final architecture. A <code>mobile/</code> epic may move to <code>shared/</code> once its code is extracted into <code>packages/core</code> (Connector Framework is the likely first candidate) — moving the file is the update, not a separate tag to remember. Epic IDs (<code>&lt;epic&gt;.&lt;seq&gt;</code>) are permanent regardless of which directory the file lives in; only the path changes.</p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Epic</th><th>Status</th><th>Summary</th></tr></thead><tbody><tr><td>0</td><td><a href="./mobile/infrastructure.html">Infrastructure</a></td><td>✅ Complete</td><td>Repo scaffold, RN project setup, CI, build tooling for iOS/Android</td></tr><tr><td>1</td><td><a href="./mobile/core-inference-chat.html">Core Inference &amp; Chat</a></td><td>✅ Complete</td><td><code>llama.rn</code>/GGUF engine, model manager, fully offline chat and writing assistant</td></tr><tr><td>2</td><td><a href="./mobile/connector-framework.html">Connector Framework</a></td><td>⏳ In Progress</td><td>Manifest schema, permission/consent model, tool-routing, tiered trust runtime — Tier 1 done, Tier 3 scaffolding (2.6) open</td></tr><tr><td>3</td><td><a href="./mobile/search-connector.html">Search Connector</a></td><td>✅ Done</td><td>Default Tier 1 connector — meta-search (SearXNG-aligned) web search</td></tr><tr><td>4</td><td><a href="./mobile/sovereign-tasks-connector.html">Sovereign Tasks Connector</a></td><td>📋 Planned</td><td>Default Tier 1 connector — direct API integration with a self-hosted <code>sovereign</code></td></tr><tr><td>7</td><td><a href="./mobile/design-system.html">Design System &amp; Branding</a></td><td>⏳ In Progress</td><td>Native theme adapting Sovereign&#39;s visual identity; standalone app, shared look</td></tr><tr><td>8</td><td><a href="./mobile/mobile-app-shell.html">Mobile App Shell</a></td><td>⏳ In Progress</td><td>The React Native app itself — iOS + Android, not a WebView wrapper</td></tr><tr><td>10</td><td><a href="./mobile/calendar-connector.html">Calendar Connector</a></td><td>⏳ In Progress</td><td>First Tier 3 connector — create/update/delete/query the device&#39;s own calendar; mobile + desktop (macOS only) done, Windows/Linux desktop scoped as a fast-follow (10.3)</td></tr><tr><td>11</td><td><a href="./mobile/device-connector.html">Device Connector</a></td><td>✅ Complete</td><td>Tier 3 connector — app-window brightness (11.1) and flashlight (11.2) both done, both verified on a real physical device</td></tr><tr><td>16</td><td><a href="./mobile/knowledge-base.html">Knowledge Base</a></td><td>📋 Planned</td><td>Opt-in on-device knowledge base — archives conversations, accepts user content, retrieval folded into the offline pipeline; no connector, no network (research 0012). A remote knowledge base is a deferred second phase</td></tr></tbody></table><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Epic</th><th>Status</th><th>Summary</th></tr></thead><tbody><tr><td>9</td><td><a href="./desktop/shell.html">Desktop Shell</a></td><td>✅ Complete</td><td>Shell technology decision — Tauri v2, over Electron and a React Native shell</td></tr><tr><td>12</td><td><a href="./desktop/core-port.html">Desktop Core Port</a></td><td>✅ Done</td><td>Secondary, optional desktop client on Tauri — on-device inference, connector framework, grammar-constrained tool-calling, minimal offline chat UI, writing-assist modes (12.1–12.7, 12.7a, 12.8)</td></tr><tr><td>13</td><td><a href="./desktop/app-shell.html">Desktop App Shell</a></td><td>✅ Done</td><td>Real navigation, model manager, connectors/permissions, and settings screens — extracted from task 12.7&#39;s single chat screen</td></tr><tr><td>14</td><td><a href="./desktop/distribution.html">Desktop Distribution &amp; Signing</a></td><td>⏳ In Progress</td><td>Real signed/notarized installer artifacts and a self-update mechanism — no app store to piggyback on; 14.1/14.3/14.4 done — real macOS/Windows/Linux releases via CI, <code>v0.1.5</code> published, update mechanism live; only 14.2 (code signing) remains, skipped for now</td></tr><tr><td>15</td><td><a href="./desktop/design-system.html">Design System &amp; Branding (Desktop)</a></td><td>✅ Complete</td><td>The desktop counterpart to epic 7 — warm cream/clay palette, icon system, and per-screen passes (15.1–15.5); 15.5&#39;s splash window was later removed, see that task&#39;s own note</td></tr></tbody></table><h2 id="shared" tabindex="-1">Shared <a class="header-anchor" href="#shared" aria-label="Permalink to &quot;Shared&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Epic</th><th>Status</th><th>Summary</th></tr></thead><tbody><tr><td>5</td><td><a href="./shared/connector-store-sdk.html">Connector Store &amp; SDK</a></td><td>⏳ In Progress</td><td>Public SDK, plugin template, examples, registry, in-app connector store</td></tr><tr><td>6</td><td><a href="./shared/monetization.html">Monetization</a></td><td>⏳ In Progress</td><td>Paid connectors — platform IAP (mobile), direct sale (desktop); entitlement model done, IAP/direct-sale blocked on real accounts</td></tr></tbody></table><p><em>Status key: ✅ Complete · ⏳ In Progress · 📋 Planned</em></p>',14)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
